SELECT analytics_order_facts.payment_method, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 8 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'enterprise' AND analytics_order_facts.category = 'category_04' GROUP BY analytics_order_facts.payment_method ORDER BY order_count DESC, analytics_order_facts.payment_method ASC LIMIT 12
